// Compute all financial & site health totals deterministically in JS.
// The LLM never performs arithmetic or invents metrics.
const stripePayload = $('Fetch Stripe 7d Charges').first().json || {};
const auditPayload = $('Run Tizuvo Site Audit').first().json || {};

const charges = Array.isArray(stripePayload.data) ? stripePayload.data : [];
let grossCents = 0;
let failedCents = 0;
let succeededCount = 0;
let failedCount = 0;

for (const ch of charges) {
  const amount = Number(ch.amount || 0);
  if (ch.paid === true && ch.status === 'succeeded') {
    grossCents += amount;
    succeededCount += 1;
  } else if (ch.status === 'failed') {
    failedCents += amount;
    failedCount += 1;
  }
}

const checks = Array.isArray(auditPayload.checks) ? auditPayload.checks : [];
const failedChecks = checks
  .filter((c) => c && (c.status === 'fail' || c.passed === false))
  .map((c) => c.name || c.id || 'unnamed-check');

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    period: {
      start_utc: weekAgo.toISOString(),
      end_utc: now.toISOString()
    },
    revenue: {
      currency: (charges[0]?.currency || 'usd').toUpperCase(),
      gross_revenue: Number((grossCents / 100).toFixed(2)),
      succeeded_charges: succeededCount,
      failed_payments: failedCount,
      failed_volume: Number((failedCents / 100).toFixed(2))
    },
    site_health: {
      target_url: $env.AUDIT_TARGET_URL || auditPayload.url || 'https://tizuvo.com',
      score: typeof auditPayload.score === 'number' ? auditPayload.score : null,
      grade: auditPayload.grade || 'N/A',
      total_checks: checks.length,
      failed_checks: failedChecks
    }
  }
}];

const metrics = $('Deterministic Metrics Aggregation').first().json;
const rawResponse = $input.first().json;
const content = rawResponse?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('AI executive brief returned empty content');
}

const brief = JSON.parse(content);
const threshold = Number($env.AI_CONFIDENCE_THRESHOLD ?? 0.80);
const bulletsMd = brief.bullets.map((b) => `• ${b}`).join('\n');
const actionsMd = brief.action_items.map((a, i) => `${i + 1}. ${a}`).join('\n');

const slackMessage = [
  `*${brief.headline}*`,
  `_Verified 7d Totals: ${metrics.revenue.currency} ${metrics.revenue.gross_revenue} gross (${metrics.revenue.succeeded_charges} paid, ${metrics.revenue.failed_payments} failed) | Site Score: ${metrics.site_health.score ?? 'N/A'}/100 (${metrics.site_health.grade})_`,
  '',
  '*Executive Summary*',
  bulletsMd,
  '',
  '*Recommended Actions*',
  actionsMd
].join('\n');

return [{
  json: {
    metrics,
    brief,
    confidence_threshold: Number.isFinite(threshold) ? threshold : 0.80,
    slack_message: slackMessage,
    email_subject: `Weekly Founder Brief: ${brief.headline}`,
    email_text: slackMessage.replace(/\*/g, '')
  }
}];

